SELECT review_rating FROM customer_behaviour.customer;
USE customer_behaviour;
SELECT * FROM customer
WHERE review_rating IS NULL;

--Q1. What is the total revenew generated by male vs female customers?

Select gender, SUM(purchase_amount) as revenue
From customer Group By Gender;

--Q2 which customer used the discount but still spent more than the average purchase amount?

Select customer_id, purchase_amount
From customer
Where discount_applied = 'Yes' and purchase_amount >= (Select AVG(purchase_amount) from customer)

--Q3. Which are th top 5 products with the highest average review rating?
USE customer_behaviour;
SELECT * FROM customer
Select item_purchased, ROUND (AVG(review_rating),2) as "average Product Rating"
From customer
Group BY item_purchased
Order BY AVG(review_rating) desc
limit 5;
--Q4. Compare  the average Amounts between standard and express shipping.

SELECT
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS average_purchase
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;

--Q5 Do subscribe customer spend more ? compare average spend and total revenue between subscribers and non-subscribers

SELECT 
    subscription_status,
    COUNT(customer_id) AS total_customer,
    ROUND(AVG(purchase_amount), 2) AS avg_spend,
    ROUND(SUM(purchase_amount), 2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;

--Q6. which 5 products have the highest percentage of purcahse with discount applied?

Select item_purchased,
ROUND(100* SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END)/COUNT(*),2) as discount_rate
from customer
Group BY item_purchased
Order BY discount_rate DESC
limit 5;

--Q7 Segment customers into New, Returning and Loyal based on their total number of previous purchases , and show the count of each segment.
 
 WITH customer_type as(
 Select customer_id, previous_purchases,
 CASE 
	WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END as customer_segment
    from customer
 )
 
Select customer_segment, count(*) as 'Number Of Customers'
From customer_type
Group BY customer_segment
	-- i have added my question to above CTE i have included categiries
	WITH customer_type AS (
		SELECT
			customer_id,
			category,
			previous_purchases,
			CASE
				WHEN previous_purchases = 1 THEN 'New'
				WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
				ELSE 'Loyal'
			END AS customer_segment
		FROM customer
	)

	SELECT
		customer_segment,
		COUNT(DISTINCT customer_id) AS number_of_customers,
		GROUP_CONCAT(DISTINCT category) AS categories
	FROM customer_type
	GROUP BY customer_segment;
    
--Q8 what are top 3 purchased products within each category

With item_counts as (
select category, item_purchased,
COUNT(customer_id) as total_orders,
ROW_NUMBER() OVER (PARTITION BY category order by COUNT(customer_id) DESC) as item_rank
from customer
group by category, item_purchased
)

Select item_rank, category, item_purchased, total_orders
from item_counts
Where item_rank <=3; #Here we have used row number because RANK and DENSE RANK assing ranking on total_orders and club category as well that is not correct anser value may repeat with products but product should merge with wrong category.
#


--Q9. Are customers who are repeate buyers (more than 5 previous purchases)

select subscription_status, 
COUNT(customer_id) as repeat_buyers
from customer
where previous_purchases > 5
group BY subscription_status

--Q10. what is the revenue contibution of each age group?

Select age_group,
SUM(purchase_amount) as total_revenue
from customer
group by age_group
order BY total_revenue DESC;
